// Package credentials issues and verifies SMTP credentials.
//
// Secrets are generated by the server with 256 bits of entropy, so a keyed
// HMAC-SHA256 is enough to store them: no slow hash and no verification cache
// are needed. Verification is constant time.
package credentials

import (
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base32"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/sandpost-mail/sandpost/internal/store"
	"github.com/sandpost-mail/sandpost/internal/store/sqlcgen"
)

const (
	usernamePrefix = "sp_"
	secretPrefix   = "sps_"
	maxLabelLength = 100
	keyContext     = "sandpost/smtp-credential/v1"
)

// Domain errors.
var (
	ErrInvalid         = errors.New("invalid credentials")
	ErrNotFound        = errors.New("credential not found")
	ErrProjectNotFound = errors.New("project not found")
	ErrLabelTooLong    = fmt.Errorf("label is longer than %d characters", maxLabelLength)
)

var usernameEncoding = base32.StdEncoding.WithPadding(base32.NoPadding)

// Credential is a stored credential, never including its secret.
type Credential struct {
	ID         int64      `json:"id"`
	ProjectID  int64      `json:"project_id"`
	Username   string     `json:"username"`
	Label      string     `json:"label"`
	CreatedAt  time.Time  `json:"created_at"`
	RevokedAt  *time.Time `json:"revoked_at"`
	LastUsedAt *time.Time `json:"last_used_at"`
}

// Issued is a freshly created credential. Secret is shown once and is not
// recoverable afterwards.
type Issued struct {
	Credential
	Secret string `json:"secret"`
}

// Identity is the result of a successful verification: the credential and the
// project it fixes for the SMTP session.
type Identity struct {
	CredentialID int64
	ProjectID    int64
}

// Service manages SMTP credentials.
type Service struct {
	q   *sqlcgen.Queries
	key []byte
}

// New returns a Service. secretKey is the instance SECRET_KEY, a dedicated
// HMAC key is derived from it.
func New(db sqlcgen.DBTX, secretKey string) *Service {
	mac := hmac.New(sha256.New, []byte(secretKey))
	mac.Write([]byte(keyContext))
	return &Service{q: sqlcgen.New(db), key: mac.Sum(nil)}
}

// Create generates a username and secret for projectID.
func (s *Service) Create(ctx context.Context, projectID int64, label string) (Issued, error) {
	label = strings.TrimSpace(label)
	if len([]rune(label)) > maxLabelLength {
		return Issued{}, ErrLabelTooLong
	}
	userRaw, err := randomBytes(8)
	if err != nil {
		return Issued{}, err
	}
	secretRaw, err := randomBytes(32)
	if err != nil {
		return Issued{}, err
	}
	username := usernamePrefix + strings.ToLower(usernameEncoding.EncodeToString(userRaw))
	secret := secretPrefix + base64.RawURLEncoding.EncodeToString(secretRaw)

	row, err := s.q.CreateCredential(ctx, sqlcgen.CreateCredentialParams{
		ProjectID:  projectID,
		Username:   username,
		SecretHmac: s.digest(secret),
		Label:      label,
	})
	if store.IsForeignKeyViolation(err) {
		return Issued{}, ErrProjectNotFound
	}
	if err != nil {
		return Issued{}, fmt.Errorf("create credential: %w", err)
	}
	return Issued{
		Credential: Credential{
			ID: row.ID, ProjectID: row.ProjectID, Username: row.Username, Label: row.Label,
			CreatedAt: row.CreatedAt, RevokedAt: row.RevokedAt, LastUsedAt: row.LastUsedAt,
		},
		Secret: secret,
	}, nil
}

// List returns every credential of a project, newest first.
func (s *Service) List(ctx context.Context, projectID int64) ([]Credential, error) {
	rows, err := s.q.ListCredentials(ctx, projectID)
	if err != nil {
		return nil, fmt.Errorf("list credentials: %w", err)
	}
	out := make([]Credential, 0, len(rows))
	for _, r := range rows {
		out = append(out, Credential{
			ID: r.ID, ProjectID: r.ProjectID, Username: r.Username, Label: r.Label,
			CreatedAt: r.CreatedAt, RevokedAt: r.RevokedAt, LastUsedAt: r.LastUsedAt,
		})
	}
	return out, nil
}

// Revoke disables a credential. It returns ErrNotFound when the credential does
// not exist in the project or is already revoked.
func (s *Service) Revoke(ctx context.Context, projectID, id int64) error {
	n, err := s.q.RevokeCredential(ctx, sqlcgen.RevokeCredentialParams{ProjectID: projectID, ID: id})
	if err != nil {
		return fmt.Errorf("revoke credential: %w", err)
	}
	if n == 0 {
		return ErrNotFound
	}
	return nil
}

// Verify checks username and secret. Every failure path returns ErrInvalid and
// does the same HMAC work, so timing does not reveal whether a username exists.
func (s *Service) Verify(ctx context.Context, username, secret string) (Identity, error) {
	got := s.digest(secret)
	row, err := s.q.GetActiveCredentialByUsername(ctx, username)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		_ = hmac.Equal(got, make([]byte, len(got)))
		return Identity{}, ErrInvalid
	case err != nil:
		return Identity{}, fmt.Errorf("lookup credential: %w", err)
	}
	if !hmac.Equal(got, row.SecretHmac) {
		return Identity{}, ErrInvalid
	}
	// Best effort bookkeeping, it must never fail an authentication.
	_ = s.q.TouchCredential(ctx, row.ID)
	return Identity{CredentialID: row.ID, ProjectID: row.ProjectID}, nil
}

func (s *Service) digest(secret string) []byte {
	mac := hmac.New(sha256.New, s.key)
	mac.Write([]byte(secret))
	return mac.Sum(nil)
}

func randomBytes(n int) ([]byte, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return nil, fmt.Errorf("random bytes: %w", err)
	}
	return b, nil
}
